def reach3(ends,hi,target,fbE):
    k=len(ends)
    S=[(k*target[0]+d0,k*target[1]+d1) for d0 in range(k) for d1 in range(k)]
    def okE(p,others):
        if not EO[p[0]][p[1]]: return False
        d=set(diamond(*p))
        return not ((d & ALLBOX) or (d & fbE) or (d & others))
    def okH(hh):
        if not HO[hh[0]][hh[1]]: return False
        if hh==target: return True
        hc=set(hubcells(*hh))
        return not ((hc & ALLBOX) or (hc & RINGCELLS))
    tot=(sum(p[0] for p in ends),sum(p[1] for p in ends))
    others0=set().union(*[set(diamond(*p)) for i,p in enumerate(ends) if i!=hi])
    for (s0,s1) in S:
        p=(s0-tot[0]+ends[hi][0], s1-tot[1]+ends[hi][1])
        if 1<=p[0]<64 and 0<=p[1]<64:
            if okE(p,others0):
                e2=list(ends); e2[hi]=p
                if okH(mean_of(e2)): return (1,[p],e2,hi)
    for j in range(k):
        if j==hi: continue
        fixed=[i for i in range(k) if i not in (hi,j)]
        for p in SAFE:
            oth=set().union(*[set(diamond(*ends[i])) for i in fixed]) if fixed else set()
            if not okE(p,oth): continue
            e1=list(ends); e1[hi]=p
            if not okH(mean_of(e1)): continue
            t=(sum(x[0] for x in e1),sum(x[1] for x in e1))
            oth2=set(diamond(*p))|set().union(*[set(diamond(*e1[i])) for i in fixed]) if fixed else set(diamond(*p))
            for (s0,s1) in S:
                q=(s0-t[0]+e1[j][0], s1-t[1]+e1[j][1])
                if not(1<=q[0]<64 and 0<=q[1]<64): continue
                if not okE(q,oth2): continue
                e2=list(e1); e2[j]=q
                if not okH(mean_of(e2)): continue
                return (3,[p,ends[j],q],e2,j)
    return None
