def rot(cells, k):
    # k x 90 CW: (r,c) -> (c, -r)
    out=set()
    for (r,c) in cells:
        rr,cc=r,c
        for _ in range(k):
            rr,cc = cc, -rr
        out.add((rr,cc))
    return out
